#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=5
local project_root
project_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$project_root"
ENV_FILE="$project_root/.env.deployment"
umask 077
[[ ! -L "$ENV_FILE" ]] || { warn "Use a regular .env.deployment file, not a symlink."; return 1; }
[[ ! -e "$ENV_FILE" ]] || chmod 600 "$ENV_FILE"
export GH_BROWSER="$project_root/scripts/open-brave.sh"
export BROWSER="$GH_BROWSER"
# Override only the browser launcher below the unchanged template library.
# The user's browser preference applies to every URL, including CLI sign-in.
open_url() {
  say "Open in Brave: $1"
  "$project_root/scripts/open-brave.sh" "$1" || warn "Open this URL in Brave manually."
}
command -v gh >/dev/null || { warn "Install the official GitHub CLI first."; return 1; }
[[ -x node_modules/.bin/vercel && -x node_modules/.bin/supabase ]] || { warn "Run npm ci first."; return 1; }
banner "Nhà Hà Nội: Vercel, Supabase and CI/CD"
say "Stages: GitHub access, new Vercel project, new Supabase project, runtime key, CI secrets."
say "Secrets stay in this ignored mode-0600 file and the appropriate service secret stores."
say "No database migration, private crawl upload, git push or deployment runs in this wizard."
pause

stage "GitHub: renew access to this repository"
# An expired injected token would otherwise override a successful CLI login.
unset GITHUB_TOKEN GH_TOKEN
if ! gh auth status >/dev/null 2>&1; then
  say "Complete the CLI's device sign-in in Brave for the account owning this repository."
  gh auth login --hostname github.com --git-protocol https --web
fi
gh auth status >/dev/null 2>&1 || return 1
gh repo view --json nameWithOwner --jq .nameWithOwner
pause "Confirm this is the app's repository, then press Enter."

stage "Vercel: token and a new project"
open_url "https://vercel.com/account/tokens"
step "Create an expiring CI token for the team/account that will own this new project."
step "Give it the narrowest scope that can create and deploy this app; later restrict it to the project."
ask_secret VERCEL_TOKEN "Paste the Vercel token here (hidden):"
[[ -n "$VERCEL_TOKEN" ]] || return 1
write_env VERCEL_TOKEN "$VERCEL_TOKEN"
npm run --silent vercel -- whoami
if [[ ! -f .vercel/project.json ]]; then
  say "Create the new project and link it. Use vn-real-estate-gpt as the project name."
  say "Choose the account/team you intended. Keep the current directory as the project root."
  if ! npm run --silent vercel -- project inspect vn-real-estate-gpt >/dev/null 2>&1; then
    npm run --silent vercel -- project create vn-real-estate-gpt
  fi
  npm run --silent vercel -- link --project vn-real-estate-gpt
fi
[[ -f .vercel/project.json ]] || { warn "Vercel did not create the local link."; return 1; }
VERCEL_ORG_ID=$(node -p 'JSON.parse(require("fs").readFileSync(".vercel/project.json","utf8")).orgId')
VERCEL_PROJECT_ID=$(node -p 'JSON.parse(require("fs").readFileSync(".vercel/project.json","utf8")).projectId')
write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
write_env VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"

stage "Supabase: new project and CLI access"
open_url "https://supabase.com/dashboard/new"
step "Create a new project named vn-real-estate-gpt in your intended organization."
step "Use the free plan if available and Singapore/ap-southeast-1 for this Hanoi pilot."
step "Generate/save its database password in your password manager. Wait until the project is ready."
step "Copy the 20-letter project reference from the project dashboard URL."
ask SUPABASE_PROJECT_REF "Supabase project reference:"
[[ "$SUPABASE_PROJECT_REF" =~ ^[a-z]{20}$ ]] || { warn "Expected the 20-letter project reference."; return 1; }
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env SUPABASE_URL "https://${SUPABASE_PROJECT_REF}.supabase.co"
ask_secret SUPABASE_DB_PASSWORD "Database password (hidden):"
[[ -n "$SUPABASE_DB_PASSWORD" ]] || return 1
write_env SUPABASE_DB_PASSWORD "$SUPABASE_DB_PASSWORD"
open_url "https://supabase.com/dashboard/account/tokens"
step "Create an expiring token scoped to this project."
step "For CLI linking, allow Project Settings, API Keys, API Key Secrets and Connection Pooling with Read access."
ask_secret SUPABASE_ACCESS_TOKEN "Paste the scoped Supabase access token (hidden):"
[[ -n "$SUPABASE_ACCESS_TOKEN" ]] || return 1
write_env SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
node scripts/check-supabase-access.mjs
npm run --silent supabase -- link --project-ref "$SUPABASE_PROJECT_REF"

stage "Runtime: server-only Supabase key and Vercel settings"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "Under API Keys, create/copy a Secret key (sb_secret_...) for this backend."
step "This is different from the CLI access token. Keep it out of the widget and chat."
ask_secret SUPABASE_SECRET_KEY "Supabase backend Secret key (hidden):"
[[ "$SUPABASE_SECRET_KEY" == sb_secret_* ]] || { warn "Expected a modern sb_secret_ key."; return 1; }
write_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
write_env SESSION_BACKEND supabase
write_env INVENTORY_MODE demo
write_env RESEARCH_LINKS_ENABLED 1
for name in SUPABASE_URL SESSION_BACKEND INVENTORY_MODE RESEARCH_LINKS_ENABLED; do
  printf '%s' "${!name}" | npm run --silent vercel -- env add "$name" --environment production --no-sensitive --force --yes
done
printf '%s' "$SUPABASE_SECRET_KEY" | npm run --silent vercel -- env add SUPABASE_SECRET_KEY --environment production --sensitive --force --yes

stage "CI/CD: save the six repository secrets"
say "These authorize this repository's production workflow to deploy this app and its schema."
for name in VERCEL_TOKEN VERCEL_ORG_ID VERCEL_PROJECT_ID SUPABASE_ACCESS_TOKEN SUPABASE_PROJECT_REF SUPABASE_DB_PASSWORD; do
  set_secret "$name" "${!name}"
done
if (( ${#SKIPPED[@]} )); then
  warn "Some GitHub secrets were not saved; deployment is not enabled yet."
fi
finish
say "Account setup is ready. Return to Codex for the first reviewed deployment."
say "The first deployment must apply migrations, sync the minimal source projection, and pass the hosted smoke check."
}

run_wizard "$@"; exit
